def make_complete_pattern():
    """
    Pattern: Each 2x2 block generates 4 diagonal rays from its corners:
    - Top-Left corner → Main diagonal going down-right: 8 (upper-left) / 6 (lower-right)
    - Top-Right corner → Anti diagonal going down-left: 3 (upper-left) / 7 (lower-left)
    """
    output = [[0]*8 for _ in range(8)]

    # Block 0: rows 1-2, cols 3-4
    # Block 1: rows 5-6, cols 1-2
    for r in range(8):
        for c in range(8):
            if 1 <= r <= 2 and 3 <= c <= 4:
                output[r][c] = 2
            elif 5 <= r <= 6 and 1 <= c <= 2:
                output[r][c] = 2

    # BLOCK 0 (rows 1-2, cols 3-4)

    # Main diagonal from Top-Left (1,3): r-c = -2
    # Upper-left (r < 1) → 8, Lower-right (r > 1, c > 3) → 6
    for r in range(8):
        c = r + 2  # on main diag
        if 0 <= c < 8:
            if 1 <= r <= 2:  # would be in block
                pass
            elif r < 1:  # upper-left
                output[r][c] = 8
            else:  # lower-right (r > 1, automatically c > 3 since c = r+2)
                output[r][c] = 6

    # Anti diagonal from Top-Right (1,4): r+c = 5
    # Upper-left (r < 2) and right → 3, Lower-left → 7
    for r in range(8):
        c = 5 - r
        if 0 <= c < 8:
            # Block check
            in_block = (1 <= r <= 2) and (3 <= c <= 4)
            if in_block:
                continue

            # Upper part (r < 2): check if "right"
            if r < 2:
                # (r < 1 and c > 4) → upper-right → 3
                # (r = 0 and c = 5) → should be 3
                if c > 3:  # right of block
                    output[r][c] = 3
            else:  # lower part (r >= 2)
                # (r = 3 and c = 2) → c < 3, left
                # c < 3 → left → 7
                if c < 3:
                    output[r][c] = 7

    # BLOCK 1 (rows 5-6, cols 1-2)

    # Main diagonal from Top-Left (5,1): r-c = 4
    for r in range(8):
        c = r - 4
        if 0 <= c < 8:
            if 5 <= r <= 6 and 1 <= c <= 2:
                pass  # block
            elif r < 5:  # upper-left
                output[r][c] = 8
            else:  # lower-right (r > 5, c > 1)
                output[r][c] = 6

    # Anti diagonal from Top-Right (5,2): r+c = 7
    for r in range(8):
        c = 7 - r
        if 0 <= c < 8:
            in_block = (5 <= r <= 6) and (1 <= c <= 2)
            if in_block:
