import json

def make_simplified_block_rays():
    """
    Simplest hypothesis: Block深刻印象 generates ONE continuous whole diagonal
    Main diagonal gets ONE value, Anti diagonal gets ONE value
    """
    output = [[0]*8 for _ in range(8)]

    # Blocks
    for r in range(8):
        for c in range(8):
            if (1 <= r <= 2) and (3 <= c <= 4):
                output[r][c] = 2
            elif (5 <= r <= 6) and (1 <= c <= 2):
                output[r][c] = 2

    # Block 0 main: 8 always
    for r in range(8):
        c = r + 2  # r-c = -2
        if 0 <= c < 8 and not (1 <= r <= 2 and 3 <= c <= 4):
            output[r][c] = 8

    # Block 0 anti: 3 always
    for r in range(8):
        c = 5 - r  # r+c = 5
        if 0 <= c < 8 and not (1 <= r <= 2 and 3 <= c <= 4):
            output[r][c] = 3

    # Block 1 main: 6 always (different!)
    for r in range(8):
        c = r - 4  # r-c = 4
        if 0 <= c < 8 and not (5 <= r <= 6 and 1 <= c <= 2):
            output[r][c] = 6

    # Block 1 anti: 7 always (different!)
    for r in range(8):
        c = 7 - r  # r+c = 7
        if 0 <= c < 8 and not (5 <= r <= 6 and 1 <= c <= 2):
            output[r][c] = 7

    return output

